				    "Error, can't read tile at %lu %lu",
				    (unsigned long) col,
				    (unsigned long) row);
 				status = 0;
 				goto done;
 			}
			if (colb > iskew) {
 				uint32 width = imagew - colb;
 				uint32 oskew = tilew - width;
 				cpStripToTile(bufp + colb,
				    tilebuf, nrow, width,
				    oskew + iskew, oskew );
			} else
				cpStripToTile(bufp + colb,
				    tilebuf, nrow, tilew,
				    iskew, 0);
